/** Actual Charge-Up Dash uses one captured until-tails result, one selection, and one shuffle. */
public final class GeneratedRuleBatch45Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static void check(boolean b,String why){GeneratedRuleBatch8Test.check(b,why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static JsonObject json(){return GeneratedRuleBatch8Test.entry("me5-5_en_042").getAsJsonArray("attacks").get(0).getAsJsonObject().deepCopy();}
    static AttackDefinition charge(){return BundledCombatData.attack(json(),EffectRegistry.standard());}
    static ServerMatch fixture(int warmup){var m=GeneratedRuleBatch44Test.fixture(charge());if(warmup>0)m.flipCoinsByEffect(A,warmup);return m;}
    static List<RandomAuditEvent> flips(ServerMatch m,int start){return m.randomTranscript().subList(start,m.randomTranscript().size()).stream().filter(e->e.operation().contains(":until-tails-")).toList();}
    static int heads(ServerMatch m,int start){var events=flips(m,start);check(!events.isEmpty()&&events.getLast().result()==1&&events.subList(0,events.size()-1).stream().allMatch(e->e.result()==0),"Coin sequence did not finish at its first actual tails");return events.size()-1;}
    static void rejectedAtomic(ServerMatch m,Runnable r){GeneratedRuleBatch44Test.assertRejectedAtomic(m,r);}
    static void submit(ServerMatch m,List<UUID> ids){var p=m.effectCardPrompt(A);m.submitEffectCards(A,p.resolutionId(),p.step(),ids);check(!m.hasPendingAttachmentTarget()&&m.effectCardReveal()==null,"Self attachment incorrectly requested another host or reveal");}
    public static void main(String[] args){normalChoices();emptyEligible();longActualSequence();sourceSwitch();schema();System.out.println("GeneratedRuleBatch45Test passed: actual Charge-Up Dash cost, until first actual tails including >20 heads, captured heads limit, own Basic Lightning only, zero/partial/all selections, empty candidates, self identity, one shuffle, no coin replay on invalid requests and strict definite-result data flow");}
    static void normalChoices(){Set<Integer> outcomes=new HashSet<>();for(String mode:List.of("zero","one","all"))for(int warm=0;warm<64;warm++){
        var m=fixture(warm);var attack=charge();check(attack.energyCost().equals(Map.of(EnergyType.COLORLESS,1)),"Printed attack cost removed");UUID source=m.activePokemonView(A).pokemonId();var deck=List.copyOf(m.privateView(A).deck());int before=m.randomTranscript().size();m.attack(A,attack.id());int h=heads(m,before);outcomes.add(Math.min(3,h));
        int selected=0;if(h>0&&m.hasPendingCardSelection()) {var p=m.effectCardPrompt(A);check(p.minimum()==0&&p.maximum()==Math.min(60,h),"Selection limit is not actual heads");check(p.candidates().stream().allMatch(c->deck.contains(c)&&c.ownerId().equals(A)&&m.cardDefinition(c.definitionId()).basicEnergy()&&c.definitionId().equals("energy")),"Search offered another owner's, Special or wrong-type Energy");check(m.clientView(B).effectSelection()==null,"Private selection leaked to opponent");int rng=m.randomTranscript().size();rejectedAtomic(m,()->m.submitEffectCards(B,p.resolutionId(),p.step(),List.of()));rejectedAtomic(m,()->m.submitEffectCards(A,UUID.randomUUID(),p.step(),List.of()));if(p.candidates().size()>h){var tooMany=p.candidates().subList(0,h+1).stream().map(CardInstance::instanceId).toList();rejectedAtomic(m,()->m.submitEffectCards(A,p.resolutionId(),p.step(),tooMany));}var special=deck.stream().filter(c->c.definitionId().equals("special")).findFirst();if(special.isPresent())rejectedAtomic(m,()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(special.get().instanceId())));check(m.randomTranscript().size()==rng,"Rejected choice re-flipped or shuffled");selected=mode.equals("zero")?0:mode.equals("one")?Math.min(1,p.candidates().size()):Math.min(h,p.candidates().size());submit(m,p.candidates().subList(0,selected).stream().map(CardInstance::instanceId).toList());}
        check(m.currentPlayer().equals(B)&&!m.hasPendingEffectChoice()&&m.activePokemonView(A).pokemonId().equals(source)&&m.activePokemonView(A).attachedEnergyIds().size()==1+selected&&!m.energyAttached(A),"Attachment count/host/normal quota or completion incorrect");check(m.privateView(A).deck().size()==deck.size()-selected,"Attachment moved wrong number of physical cards");var after=m.randomTranscript().subList(before,m.randomTranscript().size());long shuffle=after.stream().filter(e->e.operation().equals("effect-attach-deck-energy:"+A)).count();check(shuffle==Math.max(0,deck.size()-selected-1)&&flips(m,before).size()==h+1,"Search did not shuffle exactly once or rerolled named coin");
    }check(outcomes.containsAll(List.of(0,1,2,3)),"Did not cover tails-first and several head counts");}
    static void emptyEligible(){for(boolean empty:List.of(false,true)){var m=fixture(3);m.discardTopDeckCardsByEffect(A,A,m.privateView(A).deck().size());if(!empty){var ids=m.privateView(A).discard().stream().filter(c->!c.definitionId().equals("energy")).limit(3).map(CardInstance::instanceId).toList();m.recoverDiscardCardsByEffect(A,A,new ServerMatch.CardSelectionPolicy(3,3,null,null,false,Set.of()),ids,CardEffectDestination.DECK_SHUFFLED);}int before=m.randomTranscript().size(),deck=m.privateView(A).deck().size();m.attack(A,charge().id());heads(m,before);check(!m.hasPendingEffectChoice()&&m.currentPlayer().equals(B)&&m.activePokemonView(A).attachedEnergyIds().size()==1&&m.privateView(A).deck().size()==deck,"Empty eligible set prevented completion or attached an ineligible card");long shuffle=m.randomTranscript().subList(before,m.randomTranscript().size()).stream().filter(e->e.operation().equals("effect-attach-deck-energy:"+A)).count();check(shuffle==Math.max(0,deck-1),"Fail-to-find must still shuffle the remaining deck once");}}
    /** Choose a real java.util.Random seed with >20 initial heads, then use the production RNG and transcript path. */
    static void longActualSequence(){long seed=-1;for(long s=0;s<20000000;s++){var r=new Random(s);int n=0;while(n<21&&r.nextInt(2)==0)n++;if(n==21){seed=s;break;}}check(seed>=0,"No rare-sequence seed found");var m=fixture(0);try{var f=ServerMatch.class.getDeclaredField("random");f.setAccessible(true);var server=f.get(m);var raw=ServerRandom.class.getDeclaredField("random");raw.setAccessible(true);((Random)raw.get(server)).setSeed(seed);}catch(ReflectiveOperationException e){throw new AssertionError(e);}int before=m.randomTranscript().size();m.attack(A,charge().id());int h=heads(m,before);check(h>20,"Production until-tails path truncated at 20");var p=m.effectCardPrompt(A);check(p!=null&&p.maximum()==Math.min(60,h),"Attachment count did not use long captured result");submit(m,p.candidates().stream().map(CardInstance::instanceId).toList());check(m.currentPlayer().equals(B)&&flips(m,before).size()==h+1,"Long sequence repeated while resolving selection");}
    static void sourceSwitch(){boolean exercised=false;for(int warm=0;warm<40&&!exercised;warm++){var m=fixture(warm);UUID source=m.activePokemonView(A).pokemonId();UUID spare=GeneratedRuleBatch42Test.add(m,A,"plain");m.attack(A,charge().id());if(!m.hasPendingCardSelection())continue;var p=m.effectCardPrompt(A);if(p.candidates().isEmpty())continue;EventTargetBindingTest.field(m).switchActiveByEffect(A,spare);submit(m,List.of(p.candidates().getFirst().instanceId()));check(m.benchPokemonView(A).stream().filter(v->v.pokemonId().equals(source)).findFirst().orElseThrow().attachedEnergyIds().size()==2&&m.activePokemonView(A).attachedEnergyIds().isEmpty(),"SELF attachment followed mutable Active slot");exercised=true;}check(exercised,"Missing source-switch case");}
    static void schema(){var effects=json().getAsJsonArray("triggers").get(0).getAsJsonObject().getAsJsonArray("effects");var attach=effects.get(1).getAsJsonObject();for(var kv:Map.of("coin","missing","amount_mode","BAD","source","DISCARD","basic_energy_only","false","amount","1").entrySet()){var bad=json();bad.getAsJsonArray("triggers").get(0).getAsJsonObject().getAsJsonArray("effects").get(1).getAsJsonObject().addProperty(kv.getKey(),kv.getValue());reject(()->AttackProgramRules.validate(BundledCombatData.attack(bad,EffectRegistry.standard())));}var swapped=json();var es=swapped.getAsJsonArray("triggers").get(0).getAsJsonObject().getAsJsonArray("effects");var first=es.get(0);es.set(0,es.get(1));es.set(1,first);reject(()->AttackProgramRules.validate(BundledCombatData.attack(swapped,EffectRegistry.standard())));var conditional=json();var ces=conditional.getAsJsonArray("triggers").get(0).getAsJsonObject().getAsJsonArray("effects");var holder=JsonParser.parseString("{\"type\":\"conditional\",\"conditions\":[{\"type\":\"IS_ACTIVE\",\"target\":\"SELF\"}],\"effects\":[]}").getAsJsonObject();holder.getAsJsonArray("effects").add(ces.get(0));ces.set(0,holder);reject(()->AttackProgramRules.validate(BundledCombatData.attack(conditional,EffectRegistry.standard())));var effect=EffectRegistry.standard().parse(attach);for(var trigger:List.of(EffectTrigger.BEFORE_ATTACK,EffectTrigger.ONCE_PER_TURN,EffectTrigger.ON_CARD_PLAYED)){var p=new EffectProgram(List.of(new TriggeredEffects(trigger,List.of(),List.of(effect))));reject(()->ResumableProgramRules.validate(p,trigger!=EffectTrigger.ON_CARD_PLAYED,trigger));}}
}
